<?php if ($events === []): ?><div class="panel-card p-8 text-center"><p class="font-bold">Belum ada catatan untuk filter ini.</p><p class="mt-2 text-sm text-ink-muted">Perubahan sensitif akan muncul setelah dicatat.</p></div><?php else: ?>
<ol class="space-y-3" aria-label="Daftar riwayat perubahan">
    <?php foreach ($events as $event): ?>
    <li class="panel-card p-4 sm:p-5"><article><header class="flex flex-col gap-2 sm:flex-row sm:items-start sm:justify-between"><div><p class="text-xs font-bold uppercase tracking-wider text-brand-chili"><?= esc(ucfirst(str_replace('_', ' ', $event['object_type']))) ?> · #<?= esc($event['object_id']) ?></p><h3 class="mt-1 break-words font-bold"><?= esc(str_replace(['.', '_'], [' · ', ' '], $event['event_type'])) ?></h3><p class="mt-1 text-sm text-ink-muted">Oleh <?= esc($event['actor_name']) ?> (<?= esc($event['actor_username']) ?>)</p></div><time class="shrink-0 text-sm tabular-nums text-ink-muted" datetime="<?= esc(date(DATE_ATOM, strtotime($event['created_at']))) ?>"><?= esc(date('d/m/Y H:i:s', strtotime($event['created_at']))) ?></time></header>
        <?php if ($event['reason']): ?><p class="mt-3 text-sm leading-6"><span class="font-semibold">Alasan:</span> <?= esc($event['reason']) ?></p><?php endif ?>
        <?php if ($event['before_values'] || $event['after_values']): ?><details class="mt-3 border-t border-border-warm pt-3"><summary class="cursor-pointer text-sm font-bold focus-ring">Lihat nilai sebelum dan sesudah</summary><div class="mt-3 grid gap-3 lg:grid-cols-2"><?php if ($event['before_values']): ?><div><h4 class="text-xs font-bold uppercase tracking-wider text-ink-muted">Sebelum</h4><pre class="mt-2 overflow-x-auto whitespace-pre-wrap break-words bg-[#FFFCF4] p-3 text-xs leading-5"><?= esc(json_encode($event['before_values'], JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES)) ?></pre></div><?php endif ?><?php if ($event['after_values']): ?><div><h4 class="text-xs font-bold uppercase tracking-wider text-ink-muted">Sesudah</h4><pre class="mt-2 overflow-x-auto whitespace-pre-wrap break-words bg-[#FFFCF4] p-3 text-xs leading-5"><?= esc(json_encode($event['after_values'], JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES)) ?></pre></div><?php endif ?></div></details><?php endif ?>
    </article></li>
    <?php endforeach ?>
</ol>
